INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1, 62, 190805, -416.5, 2, 1000001, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1, 62, 190805, -416.5, 2, 1000002, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1, 63, 190805, -416.5, 2, 1000003, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "報酬がもらえますよ！\nチェックしてみてください", 0.0, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 2, 63, 190805, -416.5, 2, 1000004, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 2, 64, 190805, -363.0, 1, 1000005, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1, 64, 190805, -363.0, 2, 1000006, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 2, 64, 190805, -363.0, 1, 1000007, 0.0, "カリン", 1);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "今度の敵は、アタシにとっても\n放ってはおけない存在だ\n少年、アタシも全力で行くからさ\n一緒に守ろう、この世界を", 5.18, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 3, 61, 133701, -285.0, 7, 1020101, -6.0, "ラビリスタ", 10201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "退屈の吹き飛ぶような\n戦いの気配がするなぁ坊や\nさっさとワタシをそこへ連れてゆけ\n世界も守ってやるさ、ついでにな", 8.77, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 1, 61, 133901, -285.0, 2, 1020102, -2.0, "クリスティーナ", 10201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "おや、私の力が必要……と？\nグレゴールが手伝うそうですよ\n私は戦わないのか、という顔ですね\n……考えておきます", 15.5, "2030/01/01 14:59:59", "2025/01/31 12:00:00", 6, 61, 133801, -285.0, 1, 1020103, 0.0, "ネネカ", 10201);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "わたしだけの歌…\n一緒に、探してくれる…？\nあなたがいれば…\nもっとがんばれるから…", 9.061, "2030/01/01 14:59:59", "2025/02/28 12:00:00", 2, 61, 134301, -285.0, 5, 1020201, 0.0, "ランファ", 10202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "同じ唱喚士として、仲間として\n私にできることをします\n…これも、あなたが\n背中を押してくれたおかげですよ", 7.699, "2030/01/01 14:59:59", "2025/02/28 12:00:00", 1, 61, 134401, -285.0, 2, 1020202, 0.0, "チカ", 10202);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "世界の平和が私とクローチェさんに\nかかってるんですよね？\nぼっちには過大すぎる期待ですけど\nふ、二人でなら背負ってみせます！", 8.595, "2030/01/01 14:59:59", "2025/03/31 12:00:00", 1, 61, 134601, -285.0, 2, 1020301, 0.0, "アオイ", 10203);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "新しく手に入れたこの翼で…\nナイトさんがどこにいたって\nわたし、駆けつけちゃいますよっ！\nクローチェ・エアリアル発進ですっ", 7.758, "2030/01/01 14:59:59", "2025/03/31 12:00:00", 1, 61, 134501, -285.0, 2, 1020302, 0.0, "クローチェ", 10203);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "今日はダーリンとの初デート♪\n二人でショッピングして、その後は\n…って私、指名手配されてる！？\nちょ、た…助けてダーリン～！！", 7.0, "2030/01/01 14:59:59", "2025/04/30 12:00:00", 2, 61, 132302, -285.0, 6, 1020401, 0.0, "ルイズマリー", 10204);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "ルイちゃんのおばあちゃん優しくて\nいつもにこにこで、イロハ大好き♪\nでも一番好きなのは、角がすっごく\n大きくてかっこいいとこなんだ～♪", 7.904, "2030/01/01 14:59:59", "2025/04/30 12:00:00", 1, 61, 132402, -285.0, 2, 1020402, 0.0, "イロハ", 10204);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "ノゾミちゃんのおかげで売上が安定\nしてきたのに、臨時休業、痛すぎる\n…ま、ルイちゃんのために\n一肌脱ぐか。行くよイロハ～", 8.487, "2030/01/01 14:59:59", "2025/04/30 12:00:00", 4, 61, 132502, -285.0, 2, 1020403, 0.0, "ソノ", 10204);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "ヲ～ッホッホ♪\nあたくし様と同じお空気を吸える\nお幸運を噛みしめなさいですわ～♪\nヲ～ッホッホッホ～♪", 8.763, "2030/01/01 14:59:59", "2025/05/31 12:00:00", 1, 61, 134901, -285.0, 2, 1020502, 0.0, "カノン", 10205);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "いきますよ騎士さん！\nカノンさんと力を合わせて…力を…\n…本当にあの人なんなんです？\nこれまでになく不安なんですけど！", 6.417, "2030/01/01 14:59:59", "2025/05/31 12:00:00", 1, 61, 134801, -285.0, 3, 1020503, 0.0, "ツムギ", 10205);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "『願いが叶う海岸』か…怪しい\nだというのに、阿賀斗紫布菜たちは\n呑気に戯れている…見ていられない\n騎士クンは、わたしが守ってみせる", 10.335, "2030/01/01 14:59:59", "2025/06/30 12:00:00", 3, 61, 135001, -285.0, 7, 1020601, 0.0, "エリス", 10206);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "せっかくの夏休みなんだし\nたまにはビーチでゆっくりしましょ\n…え、もしかしてこの夏もあんまり\n休めなかったりする感じなの？", 6.281, "2030/01/01 14:59:59", "2025/06/30 12:00:00", 2, 61, 135101, -285.0, 4, 1020602, 0.0, "シェフィ", 10206);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "いっぱい。たべて\nおおきく。なると\nせーぎ。まもれる。はず\nお兄。いっしょに。スイカ。たべよ", 12.244, "2030/01/01 14:59:59", "2025/06/30 12:00:00", 1, 61, 135201, -285.0, 2, 1020603, 0.0, "プレシア", 10206);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "ひと夏の冒険のはじまりです！\nアネモネさんも楽しんでくれたら\n…できれば、もう少し\n仲良くなれたらうれしいな…", 6.339, "2030/01/01 14:59:59", "2025/07/31 12:00:00", 2, 61, 135301, -285.0, 8, 1020701, 0.0, "クリア", 10207);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "─幻の花…\n本当にあるのか謎─ですけど\n探すくらいは、\n付き合ってもいいです", 8.184, "2030/01/01 14:59:59", "2025/07/31 12:00:00", 7, 61, 135401, -285.0, 9, 1020702, 0.0, "アネモネ", 10207);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "あははっ！　笑う門には福来る！\n笑ってればきっと、複製世界にも\n未来はやってくるって信じてる！\nそうだよね、シナツちゃん！", 3.906, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 9, 61, 129101, -285.0, 2, 1020801, 0.0, "アイラ", 10208);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "繰り返されるリセットの先の未来\n何度願っても手に入らなかった未来\n…でも、私は諦めない。絶対にだ\nキミも同じだろ…アイラ？", 14.465, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 1, 61, 129201, -285.0, 2, 1020802, 0.0, "シナツ", 10208);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "アイラの世界のみんなも、\n一生懸命生きてるんだ…！\n…なのに、世界の危機だなんて！\nあたし、絶対、絶対力になるよ！", 8.662, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 4, 61, 100101, -285.0, 3, 1020803, 0.0, "ヒヨリ", 10208);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (401, "シナツ…もう一人の私\n彼女が大切にしている世界を\n絶対に終わらせはしない…！\n彼女と笑い合える未来のために！", 10.915, "2030/01/01 14:59:59", "2025/08/31 12:00:00", 1, 61, 100301, -285.0, 3, 1020804, 0.0, "レイ", 10208);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "あ、ど、ども…\nあ、あんま見ねぇでくれっと\nその、恥ずかしくて…\n体が熱くなって、溶けちまう…", 6.042, "2030/01/01 14:59:59", "2025/09/30 12:00:00", 1, 61, 135802, -285.0, 7, 1020901, 0.0, "ユキノ", 10209);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "なんで俺が幽霊に…意味不明だ\nこれじゃ死んでも死にきれねェ\n悪ィがこれも何かの縁だ、\nよろしく頼むぜ騎士公", 9.402, "2030/01/01 14:59:59", "2025/09/30 12:00:00", 4, 61, 135903, -285.0, 1, 1020902, 0.0, "サツキ", 10209);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "う、うじゅる…\nサツキ姉しゃまを助けるためにも\nまずは、腹ごしらえでしゅね…！\nタコ焼き、召し上がってくだしゃい", 8.16, "2030/01/01 14:59:59", "2025/09/30 12:00:00", 8, 61, 136902, -285.0, 1, 1020903, 0.0, "ルルィ", 10209);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "ひさしぶりのジオ・ゲヘナ\n歓迎パーティーで起きた殺人事件！\nランドソルの名探偵の名にかけて\n解き明かしてみせようじゃないか！", 5.0, "2030/01/01 14:59:59", "2025/10/31 12:00:00", 3, 61, 137401, -285.0, 2, 1021001, 0.0, "カスミ", 10210);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "…わたしはどこの誰なのでしょう\nどこから来てどこへ行くのでしょう\nこの事件の真相が分かれば、\n何かが掴めるような気がいたします", 8.12, "2030/01/01 14:59:59", "2025/10/31 12:00:00", 4, 61, 136001, -285.0, 1, 1021002, 0.0, "アラクネ", 10210);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "ナーナ、すいりとかろんぱとか、\nむずかしくてわかんないけど…\nお友だちとドーナツのためならっ\nせーいっぱいがんばるよっ！", 6.386, "2030/01/01 14:59:59", "2025/10/31 12:00:00", 4, 61, 136202, -285.0, 2, 1021003, 0.0, "ナーナ", 10210);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "騎士クンに想いを伝えたい…だから\nミソラちゃん、わたしがんばるね！\n…あれ？　わたし、なんでこんなに\n必死になってるんだろう…？", 7.438, "2030/01/01 14:59:59", "2025/11/30 12:00:00", 3, 61, 136402, -285.0, 4, 1021101, 0.0, "ユイ", 10211);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "騎士さんとのデートはわたしに\nお任せです★　なのでユイさんは\n安心して計画に専念して…たくさん\nドキドキしちゃってくださいね", 8.35, "2030/01/01 14:59:59", "2025/11/30 12:00:00", 1, 61, 136302, -285.0, 5, 1021102, 0.0, "ミソラ", 10211);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "新しい年がやってくるね！\nお正月の料理も飾りつけも、\nお姉ちゃんにお任せだよ♪\nみんなで楽しく新年を迎えよう！", 5.0, "2030/01/01 14:59:59", "2025/12/31 12:00:00", 1, 61, 136501, -285.0, 2, 1021201, 0.0, "シズル", 10212);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "おうちの掃除もトラブルも、 \n世界を揺るがす大ピンチも！\n今年のことは今年のうちに \nサッサと片付けちゃいますっ！", 5.25, "2030/01/01 14:59:59", "2025/12/31 12:00:00", 1, 61, 137902, -285.0, 2, 1021202, 0.0, "リノ", 10212);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "年の瀬はギルドマスターも\nつい駆け回っちゃう忙しい時期だ！\n一年いろいろあったけど\nお互いイイ年を迎えよう、少年！", 7.5, "2030/01/01 14:59:59", "2025/12/31 12:00:00", 1, 61, 106801, -285.0, 2, 1021203, 0.0, "ラビリスタ", 10212);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "漂う異国の料理の香り…それだけで\n世界中を旅した気分に浸れますね\nふふ、ほらクローチェ\nあまりはしゃぎすぎないように…♪", 8.204, "2030/01/01 14:59:59", "2026/01/31 12:00:00", 1, 61, 126501, -285.0, 2, 1021301, 0.0, "ライラエル", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "異界の姫君と煮炊きにて競い合う…\n感奮興起、いとをかし\n華やかなる祭典と相成るよう、一肌\n脱がせていただきとう存じまする", 7.176, "2030/01/01 14:59:59", "2026/01/31 12:00:00", 1, 61, 129701, -285.0, 2, 1021302, 0.0, "ネフィ＝ネラ", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "『ビストロプリンセス』のために\n料理の特訓を重ねてまいりました\nこの料理で騎士様の…い、いえ\n皆様の心とお腹を満たしますわ！", 8.602, "2030/01/01 14:59:59", "2026/01/31 12:00:00", 1, 61, 133101, -285.0, 5, 1021303, 0.0, "ヴァイオレット", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (102, "多様な味わいが織りなすハーモニー\nそれこそが我が国の矜持です\nもしもそれを乱すようであれば\nわたしも優しくはありませんよ？", 10.14, "2030/01/01 14:59:59", "2026/02/06 12:00:00", 1, 61, 138101, -285.0, 3, 1021304, 0.0, "ライラエル", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (202, "煉獄の穢土にてひと際輝く民草の心\n此れを守護りまするがわっちの責務\n如何な困難待ち受けようと\n不退転の矜持に揺らぎはありんせん", 10.152, "2030/01/01 14:59:59", "2026/02/06 12:00:00", 1, 61, 138201, -285.0, 7, 1021305, 0.0, "ネフィ＝ネラ", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (302, "裏世界の皆様は危機を脱し、\n残るはランドソルの皆様のみ…\n彼らを救い出すために、どうか…\nお立ち下さいペコリーヌ姫…！", 9.688, "2030/01/01 14:59:59", "2026/02/06 12:00:00", 4, 61, 138001, -285.0, 3, 1021306, 0.0, "ヴァイオレット", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (401, "みなさん、お待たせしちゃいました\nペコリーヌ、完全復活です☆\nみなさんの食卓を守るため\nもう二度と、わたしはめげません！", 5.928, "2030/01/01 14:59:59", "2026/02/12 12:00:00", 2, 61, 138301, -285.0, 1, 1021307, 0.0, "ペコリーヌ", 10213);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "成行きで参加することになっちゃっ\nた尻相撲大会。ううっ、恥ずかしい\nけどやるしかないよね。…騎士さん\nいっぱい応援してくださいね？", 9.19, "2030/01/01 14:59:59", "2026/02/28 12:00:00", 4, 61, 138702, -285.0, 2, 1021401, 0.0, "ワカナ", 10214);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "「お姉ちゃんを守れる自分になる」\nあの日の約束、今こそ果たしてみせ\nます。例えお姉ちゃんに背くことに\nなっても。例えそれが尻相撲でも！", 8.724, "2030/01/01 14:59:59", "2026/02/28 12:00:00", 1, 61, 138802, -285.0, 3, 1021402, 0.0, "シオリ", 10214);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "私がへんたいふしんしゃさんって…\nただ生きているだけなのに、ひどい\n…まぁ死んでるんですけど…とか\n言ってる暇もない感じですか？", 7.758, "2030/01/01 14:59:59", "2026/03/31 12:00:00", 4, 61, 138902, -285.0, 1, 1021501, 0.0, "グレイス", 10215);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "あの、助けてください！\n私がへんたいふしんしゃさんに\nなっちゃったみたいなんです…！\nどういう意味かは私もわかりません", 6.375, "2030/01/01 14:59:59", "2026/03/31 12:00:00", 6, 61, 139002, -285.0, 4, 1021502, 0.0, "キョウカ", 10215);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "ましゃか、グレイス姉しゃまたちが\nへんたいふしんしゃさんだなんて…\n騎士しゃん。あたちたちも協力ちて\n二人の破滅エンドを回避ちましょう", 6.173, "2030/01/01 14:59:59", "2026/03/31 12:00:00", 6, 61, 136902, -285.0, 1, 1021503, 0.0, "ルルィ", 10215);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "違う世界に来ちゃうし、\n驚きの連続だけど…\nわたしも精いっぱい頑張ります！\nアストルムのみんなと一緒に！", 4.202, "2030/01/01 14:59:59", "2026/04/30 12:00:00", 6, 61, 139202, -285.0, 2, 1021601, 0.0, "ミホ", 10216);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "想定外の事象が発生したな…だが\nいかなる苦境も切り抜けてみせる\nいつもの自分とは違う姿になっても\nわたしはわたし、西住流だ", 2.842, "2030/01/01 14:59:59", "2026/04/30 12:00:00", 6, 61, 139302, -285.0, 1, 1021602, 0.0, "マホ", 10216);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "何でこんなことになっているのか\n全然わからないけど、迷ってる暇は\nないわ。黒森峰の次期隊長として、\n前進あるのみ！　これも戦車道よ！", 4.598, "2030/01/01 14:59:59", "2026/04/30 12:00:00", 4, 61, 139402, -285.0, 1, 1021603, 0.0, "エリカ", 10216);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "わたくしたちの悲願は、ロストさせ\nてしまった方々をお助けすること…\nそのためなら、どのような辛苦にも\n耐え抜いてみせます…！", 6.533, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 4, 61, 125802, -285.0, 3, 1021701, 0.0, "リリ", 10217);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (301, "みんなも。せーぎも。\nクリアも。パパ、も。\nぜったい、たすける。\nみててね。お兄。", 5.0, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 3, 61, 126102, -285.0, 3, 1021702, 0.0, "プレシア", 10217);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "癒しの力を使うこと…\nもう、ためらいません！\nモネちゃんやお兄さん…\nみんなに許してもらうためにも！", 5.214, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 3, 61, 126002, -285.0, 4, 1021703, 0.0, "クリア", 10217);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (102, "ヴァルキュリア─皆様を助けたい\nという願いを、力にできるのなら…\nわたくしたちは、きっと誰にも\n負けません！　一意専心です…！", 8.781, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 1, 61, 139501, -285.0, 3, 1021704, 0.0, "リリ", 10217);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (202, "このヴァルキュリアって職業、\nまるで天使みたいな格好ですよね\nうーん…『聖女』ちゃんって\n呼ばれるよりは、マシかな？", 6.529, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 2, 61, 139601, -285.0, 1, 1021705, 0.0, "クリア", 10217);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (302, "ばるきり。もーど。\nはね。まっしろ。\nはっぴーちゃんと。おなじ。\nいいかんじ。", 3.195, "2030/01/01 14:59:59", "2026/05/31 12:00:00", 3, 61, 139701, -285.0, 2, 1021706, 0.0, "プレシア", 10217);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "ダーリンと一緒に南の島で\nリゾート開発なんて夢みたい♪\nああ…幸せ、最高の夏だわ…\n触れたら爆発さえしなければ～…っ", 12.43, "2030/01/01 14:59:59", "2026/06/30 12:00:00", 2, 61, 139902, -285.0, 3, 1021801, 0.0, "ルイズマリー", 10218);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "青い空、白い雲…無人島リゾートで\n大儲けですわ～♪　こらこらそこ、\nイチャついてるんじゃないですのよ\n触れたらドカンですわよ、ドカン！", 6.35, "2030/01/01 14:59:59", "2026/06/30 12:00:00", 2, 61, 140001, -285.0, 3, 1021802, 0.0, "クレジッタ", 10218);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (101, "みんなはかわいいぼくを見られて、\nぼくはみんなからラヴをもらう♡\n最高のウィンウィンだよね、これ♡\nで、最後はお兄さんをドレーに…♡", 10.23, "2030/01/01 14:59:59", "2026/07/31 12:00:00", 1, 61, 140102, -285.0, 5, 1021901, 0.0, "フブキ", 10219);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (201, "けんぞくとたくさん遊ぶためにも、\nみんなからラヴをもらわなくちゃ♪\nバズっちゃおー作戦、\n一緒に考えてね！　けんぞくぅ♪", 5.584, "2030/01/01 14:59:59", "2026/07/31 12:00:00", 1, 61, 140201, -285.0, 2, 1021902, 0.0, "ヴァンピィ", 10219);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (1, "ミッションをクリアすると、\n報酬がもらえますよ！\n頑張ってください", 3.414, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 1, 62, 190801, -416.5, 2, 2000001, 0.0, "カリン", 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (2, "ミッションをクリアして、\n報酬をゲットしましょう！", 3.099, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 1, 62, 190801, -416.5, 2, 2000002, 0.0, "カリン", 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (3, "受け取ることができる\n報酬があるようです\n確認してみてください", 2.801, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 1, 63, 190801, -416.5, 2, 2000003, 0.0, "カリン", 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (4, "報酬がもらえますよ！\nチェックしてみてください", 0.0, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2, 63, 190801, -416.5, 2, 2000004, 0.0, "カリン", 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (5, "ギルド管理協会です！\nイベント報酬券をお持ちでしたら、様々なアイテムと交換できますよ", 2.12, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2, 64, 190801, -363.0, 1, 2000005, 0.0, "カリン", 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (6, "お疲れさまです！\nこちらでイベント報酬券とアイテムを交換することができますよ", 1.68, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 1, 64, 190801, -363.0, 2, 2000006, 0.0, "カリン", 2);
INSERT INTO `v1_f4dee4921398b6ce3a6b064828e85d1a32629cd34200ef45e74826ef8339d0ee` VALUES (7, "いつもありがとうございます！\n報酬交換ですか？\nでは、イベント報酬券とお引き換えいたしますね", 2.33, "2030/01/01 14:59:59", "2026/04/10 12:00:00", 2, 64, 190801, -363.0, 1, 2000007, 0.0, "カリン", 2);
